For me the fix was this:

**Before**
` @VirtualColumn({
    query: (alias) => // here was my query
  })
  public count!: number;
  `
  
  **Solution:**
` @VirtualColumn({
    query: (alias) => safeVirtualColumnQuery(alias, // here is my query)
  })
  public count!: number;
  `
  
function safeVirtualColumnQuery(alias: string, query: string): string {
  return `SELECT CASE WHEN ${alias}.id IS NULL THEN NULL ELSE (${query}) END`;
}
